/**
 * Order Controller — Handles order lifecycle requests.
 * Generated by BackendForge
 */
const orderService = require('../services/order.service');

const orderController = {
  async createOrder(req, res, next) {
    try {
      const order = await orderService.createOrder(req.userId, req.body);
      res.status(201).json({ success: true, message: 'Order placed successfully', data: { order } });
    } catch (error) { next(error); }
  },

  async getOrderById(req, res, next) {
    try {
      const order = await orderService.getOrderById(req.params.id, req.userId, req.user.role);
      res.json({ success: true, data: { order } });
    } catch (error) { next(error); }
  },

  async cancelOrder(req, res, next) {
    try {
      const order = await orderService.cancelOrder(req.params.id, req.userId, req.body.reason);
      res.json({ success: true, message: 'Order cancelled successfully', data: { order } });
    } catch (error) { next(error); }
  },
};

module.exports = orderController;
